"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[2,1],[4,1],[6,1],[2,2],[4,2],[6,2]];
let variant=OrionProgress.variant('dilution'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,amount=0,volume=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){const[a,b]=journeys[v];return {a,b,refVolume:s===0?b:2*b,fixed:s===1,larger:s===2};}
function setValue(key,n){if(solved||!Number.isInteger(n))return;const q=challenge();if(key==='amount'&&n>=0&&n<=12&&!q.fixed)amount=n;else if(key==='volume'&&n>=(q.fixed?q.b:1)&&n<=8)volume=n;else return;state='ready';render();}
function resetTrial(){const q=challenge();amount=q.fixed?q.a:0;volume=q.fixed?q.b:1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('dilution')){variant=v;stage=0;resetTrial();}
function matches(a,v,q=challenge()){return a*q.refVolume===q.a*v&&(!q.fixed||a===q.a)&&(!q.larger||v>q.refVolume);}
function check(){if(solved)return;if(!matches(amount,volume))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('tint');}render();if(solved&&stage<2)$('next').focus();}
function vessel(x,a,v,label){const h=v*19,c=a/v,light=85-50*c/(1+c);return `<g transform="translate(${x},0)"><path d="M10 35V205H140V35" fill="#bfdce41a" stroke="#b3dce8" stroke-width="3"/><rect x="12" y="${204-h}" width="126" height="${h}" fill="hsl(207 70% ${light}%)"/>${Array.from({length:8},(_,i)=>`<path d="M10 ${204-(i+1)*19}H23" stroke="#fbf5d0"/>`).join('')}<text x="75" y="24" text-anchor="middle">${label}</text><text x="75" y="232" text-anchor="middle">${a} / ${v}</text></g>`;}
function drawing(){const q=challenge();return `<svg viewBox="0 0 350 250" role="img" aria-label="${t(`Reference ${q.a} colour units in ${q.refVolume} cups. Yours ${amount} units in ${volume} cups.`,`參考：${q.a} 份色素、${q.refVolume} 杯溶液。你的：${amount} 份、${volume} 杯。`)}"><g fill="#f4e9c4" font-size="16">${vessel(10,q.a,q.refVolume,t('Reference','參考'))}${vessel(185,amount,volume,t('Your mixture','你的溶液'))}</g></svg>`;}
function hints(){const q=challenge();return[t('Compare how much dissolved colour there is for each cup, not just the total colour amount.','比較每杯含多少已溶色素，不要只看色素總量。'),t('More water with the same colour amount makes a more dilute solution. Scaling colour and volume together keeps concentration the same.','色素量不變，加水會令溶液更稀。色素量與體積同比例增加，濃度不變。'),q.fixed?t(`Keep ${q.a} colour units and set the final volume to ${q.refVolume} cups.`,`保持 ${q.a} 份色素，將最後溶液體積設為 ${q.refVolume} 杯。`):q.larger?t(`Try ${q.a*2} units in ${q.refVolume*2} cups. Both numbers double.`,`試試 ${q.a*2} 份色素、${q.refVolume*2} 杯溶液。兩個數都加倍。`):t(`Try ${q.a} units in ${q.refVolume} cups, then compare other matching mixtures.`,`試試 ${q.a} 份色素、${q.refVolume} 杯溶液，再比較其他相同濃度的配方。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Colour Spring · Orion','彩泉秘境 · Orion');$('stageTitle').textContent=t(`Spring ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道彩泉 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Spring seals · ${p} / 3`,`彩泉封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('amount').value=amount;$('volume').value=volume;$('amount').disabled=solved||q.fixed;$('volume').disabled=solved;$('volume').min=q.fixed?q.b:1;$('amountValue').textContent=amount;$('volumeValue').textContent=volume;
$('goal').textContent=q.fixed?t(`Keep all ${q.a} colour units. Add water to dilute the original ${q.b}-cup mixture to HALF its concentration. Match the reference.`,`保留全部 ${q.a} 份色素。加水，將原本 ${q.b} 杯溶液稀釋至一半濃度，與參考相同。`):q.larger?t(`Make MORE than ${q.refVolume} cups with the SAME concentration as the reference.`,`製作多於 ${q.refVolume} 杯溶液，濃度要與參考相同。`):t('Match the reference concentration. Adjust dissolved colour and final solution volume.','配出與參考相同的濃度。調整已溶色素量和最後溶液體積。');$('reading').textContent=t(`Yours: ${amount} ÷ ${volume} = ${(amount/volume).toFixed(2)} colour units per cup.`,`你的：${amount} ÷ ${volume} = ${(amount/volume).toFixed(2)} 份色素／杯。`);$('reference').textContent=t(`Reference: ${q.a} units in ${q.refVolume} cups. Readings rounded to 2 decimal places; matches use exact ratios.`,`參考：${q.a} 份色素、${q.refVolume} 杯溶液。讀數取兩位小數；判定使用精確比例。`);const messages={ready:['Explore the mixture, then test the spring seal.','探索溶液，再測試彩泉封印。'],wrong:['Not quite. Compare the ratio and check the volume requirement. Try again.','還未吻合。比較比例，檢查體積要求，再試一次。'],success:['The spring seal shines. Your concentration matches!','彩泉封印亮起來了，濃度吻合！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('tint')?t('Tint Sigil saved in your collection.','彩泉符印已存入收藏。'):'';}
for(const key of ['amount','volume'])$(key).oninput=e=>setValue(key,Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('dilution',variant);observedVariant=OrionProgress.variant('dilution');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('tint');render();};function syncProgress(){const v=OrionProgress.variant('dilution'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('tint')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
